-- Neue Vorhabentitel als Schlagworte (nur fehlende, hoechstens 15 je Thema).
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['daten und wahrscheinlichkeit']) w where w <> all(schlagworte)) where thema_key = 'bedingte_wahrscheinlichkeit';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['anteil, bruchteil und ganzes', 'einführung der rationalen zahlen']) w where w <> all(schlagworte)) where thema_key = 'brueche';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['exponentielle funktionen', 'bakterienwachstum und radioaktiver zerfall', 'modellieren mit exponentiellen funktionen']) w where w <> all(schlagworte)) where thema_key = 'exponentialfunktionen';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['flächen- und rauminhalt', 'flächen vergleichen, vermessen, berechnen', 'flächen – größe und umfang ebener figuren']) w where w <> all(schlagworte)) where thema_key = 'flaeche_umfang';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['umfang und flächeninhalt von figuren', 'termumformungen anschaulich', 'umfang, flächeninhalt zusammengesetzter figuren']) w where w <> all(schlagworte)) where thema_key = 'flaechen_vielecke';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['strukturen erkennen und beschreiben', 'beziehungen zwischen zahlen und größen', 'zusammenhänge beschreiben']) w where w <> all(schlagworte)) where thema_key = 'ganze_zahlen_groessen';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['berechnungen an körpern']) w where w <> all(schlagworte)) where thema_key = 'koerper_pyramide_kegel_kugel';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['π und die kreisberechnung', 'längen und flächen in figuren und körpern']) w where w <> all(schlagworte)) where thema_key = 'kreis';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['wie funktioniert das? den geraden auf der spur']) w where w <> all(schlagworte)) where thema_key = 'lineare_funktionen';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['rechnen mit größen und einheiten']) w where w <> all(schlagworte)) where thema_key = 'natuerliche_zahlen';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['der satz des pythagoras und körper', 'der satz des pythagoras']) w where w <> all(schlagworte)) where thema_key = 'pythagoras';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['quadratische zusammenhänge']) w where w <> all(schlagworte)) where thema_key = 'quadratische_funktionen';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['quadratische funktionen & gleichungen', 'quadratische funktionen und gleichungen', 'nullstellen quadratischer funktionen']) w where w <> all(schlagworte)) where thema_key = 'quadratische_gleichungen';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['rechnen mit rationalen zahlen', 'erweiterung des zahlenbereichs', 'erweiterung des zahlbereichs']) w where w <> all(schlagworte)) where thema_key = 'rationale_zahlen';
