update public.themen set schlagworte = schlagworte || array(select w from unnest(array['trigonometrische funktionen', 'funktionen als modell der wirklichkeit', 'die sinusfunktion']) w where w <> all(schlagworte)) where thema_key = 'sinusfunktion';
update public.themen set schlagworte = schlagworte || array(select w from unnest(array['wie lügt man mit statistik']) w where w <> all(schlagworte)) where thema_key = 'statistik_beurteilen';
